import * as pdfjs from './vendor/pdf.mjs';
import {detectLanguage,sentences,buildQueue,extractLines} from './core.mjs';
pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;
const $=id=>document.getElementById(id),speech=window.speechSynthesis;
const names={id:'Indonesia',en:'English',ar:'Arab',fr:'Français',de:'Deutsch',es:'Español',ja:'日本語',und:'Belum yakin — pilih bahasa secara manual'};
let pages=[],pdf=null,kind='',current=0,detected='und',voices=[],queue=[],position=0,state='idle',generation=0,loading=0,rendering=0,activeUtterance=null,previewTask=null,view='text';
function notice(text){$('message').textContent=text;$('message').hidden=!text;}
function status(text){$('status').textContent=text;$('status').hidden=!text;}
function language(){return $('language').value==='auto'?detected:$('language').value;}
function selectedVoice(){return voices.find(v=>v.voiceURI===$('voice').value);}
function refreshVoices(){const old=$('voice').value;voices=speech?.getVoices()||[];const lang=language();const list=voices.filter(v=>v.lang.split(/[-_]/)[0]===lang);$('voice').replaceChildren();
 if(!list.length){const o=new Option(lang==='und'?'Pilih bahasa terlebih dahulu':'Suara bahasa ini belum tersedia','');$('voice').add(o);}else list.forEach(v=>$('voice').add(new Option(`${v.name} · ${v.localService?'lokal':'daring'}`,v.voiceURI)));
 if(list.some(v=>v.voiceURI===old))$('voice').value=old;
 voiceNote();controls();}
function voiceNote(){const v=selectedVoice();$('voiceNote').textContent=v?(v.localService?'Suara lokal dari perangkat Anda.':'Suara daring: teks dapat diproses oleh layanan suara browser.'):'Coba bahasa lain atau pasang suara bahasa ini di pengaturan perangkat.';}
function controls(){const ready=pages.length>0&&selectedVoice()&&speech; $('play').disabled=!ready;$('sample').disabled=!selectedVoice()||!speech;$('stop').disabled=state==='idle';$('previous').disabled=!queue.length;$('next').disabled=!queue.length;$('play').textContent=state==='playing'?'Ⅱ  Jeda':state==='paused'?'▶  Lanjutkan':'▶  Mulai membaca';}
function cancel(resetQueue=false){generation++;speech?.cancel();activeUtterance=null;state='idle';if(resetQueue){queue=[];position=0;$('progress').style.width='0%';}controls();}
function resetPlayback(){cancel(true);$('playTitle').textContent=pages.length?'Siap dibacakan':'Siap mendengarkan?';let estimate='Atur bacaan, lalu tekan mulai';if(pages.length){try{const [a,b]=range();const words=pages.slice(a-1,b).reduce((n,p)=>n+p.text.split(/\s+/).filter(Boolean).length,0);estimate='Estimasi '+Math.max(1,Math.ceil(words/(160*Number($('speed').value))))+' menit · rentang pilihan';}catch{}}$('playDetail').textContent=pages.length?estimate:'Buka dokumen untuk mulai membaca';document.querySelectorAll('.sentence.active').forEach(e=>e.classList.remove('active'));}
function setTabs(next){view=next;$('textTab').classList.toggle('active',next==='text');$('pdfTab').classList.toggle('active',next==='pdf');$('textTab').setAttribute('aria-selected',next==='text');$('pdfTab').setAttribute('aria-selected',next==='pdf');$('textView').hidden=next!=='text';$('pdfView').hidden=next!=='pdf';$('edit').hidden=next==='pdf';if(next==='pdf')renderPDF();}
async function renderPDF(){if(!pdf)return;const token=++rendering;try{if(previewTask){previewTask.cancel();try{await previewTask.promise;}catch{}}if(token!==rendering)return;const p=await pdf.getPage(current+1);if(token!==rendering)return;const viewport=p.getViewport({scale:1.4});const c=$('pdfCanvas');c.width=viewport.width;c.height=viewport.height;previewTask=p.render({canvasContext:c.getContext('2d'),viewport});await previewTask.promise;}catch(e){if(e.name!=='RenderingCancelledException')notice('Pratinjau belum dapat ditampilkan. Teks bacaan tetap tersedia.');}}
function renderPage(){const unit=kind==='pdf'?'Halaman':'Bagian';$('pageInfo').textContent=`${unit} ${current+1} / ${pages.length}`;$('prevPage').disabled=current===0;$('nextPage').disabled=current===pages.length-1;$('editor').hidden=true;
 $('textView').replaceChildren();const lines=sentences(pages[current]?.text||'',language());if(!lines.length){const p=document.createElement('p');p.textContent='Tidak ada teks yang dapat dibaca pada halaman ini. Bisa berupa halaman kosong atau hasil scan. OCR belum tersedia.';$('textView').append(p);}
 lines.forEach((text,i)=>{const b=document.createElement('button');b.className='sentence';b.dir='auto';b.textContent=text;b.dataset.index=i;b.title='Mulai membaca dari kalimat ini';b.onclick=()=>startAt(current,i);$('textView').append(b);});if(view==='pdf')renderPDF();highlight();}
function highlight(){const item=queue[position];document.querySelectorAll('.sentence').forEach((b,i)=>b.classList.toggle('active',!!item&&item.page===current&&item.index===i));}
function showDocument(name,size){$('empty').hidden=true;$('document').hidden=false;$('fileName').textContent=name;$('fileKind').textContent=kind==='pdf'?'DOKUMEN PDF':kind==='docx'?'DOKUMEN WORD':'TEKS CONTOH';$('fileMeta').textContent=`${pages.length} ${kind==='pdf'?'halaman':'bagian'}${size?' · '+(size/1024/1024).toFixed(2)+' MB':''} · Diproses di perangkat`;
 $('scope').disabled=false;$('scope').value='all';$('scope').options[1].text=kind==='pdf'?'Halaman saat ini':'Bagian saat ini';$('scope').options[2].text=kind==='pdf'?'Rentang halaman':'Rentang bagian';$('rangeFields').hidden=true;$('from').value=1;$('to').value=pages.length;$('from').max=pages.length;$('to').max=pages.length;$('pdfTab').disabled=!pdf;
 $('rangeNote').textContent=kind==='docx'?'Word dibagi per paragraf. Gunakan PDF untuk rentang halaman asli.':kind==='pdf'?'Nomor mengikuti halaman fisik PDF, bukan nomor yang tercetak.':'Setiap bagian berisi satu paragraf contoh.';
 detected=detectLanguage(pages.map(p=>p.text).join(' '));$('detected').textContent=`Perkiraan bahasa: ${names[detected]}.`;$('language').value='auto';current=0;setTabs('text');renderPage();refreshVoices();resetPlayback();}
async function loadFile(file){if(!file)return;notice('');if(file.size>20*1024*1024){notice('Ukuran file melebihi 20 MB. Pilih file yang lebih kecil.');return;}const ext=file.name.split('.').pop().toLowerCase();if(!['pdf','docx'].includes(ext)){notice('Gunakan PDF atau DOCX. Simpan file .doc lama sebagai .docx terlebih dahulu.');return;}
 const job=++loading;cancel(true);status('Membaca dokumen…');$('upload').disabled=true;let newPdf=null;
 try{const buffer=await file.arrayBuffer();let result=[];
 if(ext==='pdf'){const header=new TextDecoder().decode(buffer.slice(0,1024));if(!header.includes('%PDF-'))throw new Error('Isi file bukan PDF yang valid.');newPdf=await pdfjs.getDocument({data:buffer,isEvalSupported:false}).promise;if(newPdf.numPages>100)throw new Error('PDF maksimal 100 halaman. Pisahkan dokumen menjadi beberapa file.');
 for(let i=1;i<=newPdf.numPages;i++){if(job!==loading){await newPdf.destroy();return;}status(`Mengekstrak halaman ${i} dari ${newPdf.numPages}…`);const p=await newPdf.getPage(i);const content=await p.getTextContent();result.push({text:extractLines(content.items)});}}
 else{const sig=new Uint8Array(buffer,0,Math.min(buffer.byteLength,2));if(sig[0]!==80||sig[1]!==75)throw new Error('File DOCX tidak valid. Simpan ulang dokumen melalui Word.');const extracted=await window.mammoth.extractRawText({arrayBuffer:buffer});if(extracted.value.length>1000000)throw new Error('Teks Word terlalu panjang. Pisahkan dokumen menjadi beberapa file.');result=extracted.value.split(/\n\s*\n/).map(s=>({text:s.trim()})).filter(p=>p.text);if(!result.length)throw new Error('Tidak ditemukan teks dalam dokumen Word.');}
 if(job!==loading){await newPdf?.destroy();return;}cancel(true);await pdf?.destroy();pdf=newPdf;pages=result;kind=ext;showDocument(file.name,file.size);
 const blanks=pages.map((p,i)=>!p.text.trim()?i+1:null).filter(Boolean);notice(blanks.length?`Halaman ${blanks.join(', ')} tidak memiliki teks terbaca (kosong atau scan). Pilih rentang tanpa halaman tersebut. OCR belum tersedia.`:ext==='pdf'?'Periksa urutan teks, terutama pada tabel atau dokumen beberapa kolom.':'Untuk memilih halaman asli Word, simpan dokumen sebagai PDF lalu buka kembali.');
 }catch(e){await newPdf?.destroy();if(job===loading)notice(e.name==='PasswordException'?'PDF dilindungi kata sandi. Buka kuncinya lalu simpan salinan untuk dibaca.':e.message||'Dokumen gagal dibaca. Coba simpan ulang file.');}
 finally{if(job===loading){status('');$('upload').disabled=false;controls();$('file').value='';}}}
function range(){const mode=$('scope').value;return mode==='all'?[1,pages.length]:mode==='current'?[current+1,current+1]:[Number($('from').value),Number($('to').value)];}
function prepare(){const [from,to]=range();const q=buildQueue(pages,from,to,language());if(pages.slice(from-1,to).some(p=>!p.text.trim()))throw new Error('Rentang ini memuat halaman kosong atau scan yang belum dapat dibaca. Pilih rentang halaman berisi teks.');if(!q.length)throw new Error('Tidak ada teks dalam rentang pilihan.');return q;}
function begin(){try{if(!selectedVoice())throw new Error('Pilih bahasa dan suara yang tersedia terlebih dahulu.');queue=prepare();position=0;notice('');speak();}catch(e){notice(e.message);}}
function startAt(page,index){if(!selectedVoice()){notice('Pilih bahasa dan suara terlebih dahulu.');return;}try{const q=prepare();const i=q.findIndex(x=>x.page===page&&x.index===index);if(i<0)throw new Error('Kalimat ini berada di luar rentang pilihan. Ubah rentang untuk membacanya.');cancel();queue=q;position=i;notice('');speak();}catch(e){notice(e.message);}}
function speak(){if(!queue.length)return;if(position>=queue.length){cancel();$('progress').style.width='100%';$('playTitle').textContent='Bacaan selesai';$('playDetail').textContent='Seluruh rentang pilihan telah dibaca';position=0;return;}
 const voice=selectedVoice();if(!voice){cancel();notice('Suara tidak tersedia. Pilih ulang suara pembaca.');return;}cancel();const token=generation;const item=queue[position];const utterance=new SpeechSynthesisUtterance(item.text);activeUtterance=utterance;utterance.voice=voice;utterance.lang=voice.lang;utterance.rate=Number($('speed').value);utterance.volume=Number($('volume').value);
 utterance.onstart=()=>{if(token!==generation)return;state='playing';controls();$('playTitle').textContent='Sedang membaca';$('playDetail').textContent=`${kind==='pdf'?'Halaman':'Bagian'} ${item.page+1} · Kalimat ${position+1}/${queue.length}`;if($('autoscroll').checked&&current!==item.page){current=item.page;renderPage();}highlight();if($('autoscroll').checked){const b=$('textView').querySelector('.active');if(b)$('textView').scrollTo({top:Math.max(0,b.offsetTop-$('textView').offsetTop-60),behavior:'smooth'});}$('progress').style.width=`${position/queue.length*100}%`;};
 utterance.onend=()=>{if(token!==generation)return;position++;speak();};utterance.onerror=e=>{if(token!==generation)return;cancel();notice(`Suara berhenti (${e.error}). Coba pilih suara lain dan mulai lagi.`);};state='playing';controls();speech.speak(utterance);}
$('play').onclick=()=>{if(state==='playing'){speech.pause();state='paused';$('playTitle').textContent='Dijeda';controls();}else if(state==='paused'){speech.resume();state='playing';$('playTitle').textContent='Sedang membaca';controls();}else begin();};
$('stop').onclick=()=>{cancel();$('playTitle').textContent='Dihentikan';$('playDetail').textContent='Klik kalimat untuk melanjutkan dari bagian itu';};
$('previous').onclick=()=>{position=Math.max(0,position-1);speak();};$('next').onclick=()=>{position++;speak();};
$('sample').onclick=()=>{const voice=selectedVoice();if(!voice)return;cancel(true);const examples={id:'Selamat datang di Code Reader. Pilih dokumen Anda, lalu mari mulai membaca.',en:'Welcome to Code Reader. Open your document, take a breath, and enjoy the story.',ar:'مرحباً بك. اختر المستند الذي تريد قراءته.',fr:'Bienvenue. Écoutez votre document.',de:'Willkommen. Hören Sie Ihr Dokument.',es:'Bienvenido. Escucha tu documento.',ja:'ようこそ。文章を読み上げます。'};const u=new SpeechSynthesisUtterance(examples[language()]||examples.en);u.voice=voice;u.lang=voice.lang;u.rate=Number($('speed').value);u.volume=Number($('volume').value);const token=generation;activeUtterance=u;state='sample';controls();$('playTitle').textContent='Contoh suara';u.onend=()=>{if(token===generation)resetPlayback();};u.onerror=()=>{if(token===generation){resetPlayback();notice('Contoh suara gagal diputar. Coba suara lain.');}};speech.speak(u);};
$('language').onchange=()=>{resetPlayback();refreshVoices();if(pages.length)renderPage();};$('voice').onchange=()=>{resetPlayback();voiceNote();controls();};$('speed').oninput=()=>{$('speedValue').textContent=Number($('speed').value)+'×';};$('speed').onchange=resetPlayback;$('volume').onchange=()=>{if(state!=='idle'){cancel();notice('Volume diperbarui. Klik kalimat untuk melanjutkan.');}};
$('scope').onchange=()=>{resetPlayback();$('rangeFields').hidden=$('scope').value!=='range';};$('from').onchange=resetPlayback;$('to').onchange=resetPlayback;
$('prevPage').onclick=()=>{if(current>0){resetPlayback();current--;renderPage();}};$('nextPage').onclick=()=>{if(current<pages.length-1){resetPlayback();current++;renderPage();}};
$('textTab').onclick=()=>setTabs('text');$('pdfTab').onclick=()=>setTabs('pdf');
$('edit').onclick=()=>{resetPlayback();$('textView').hidden=true;$('editor').hidden=false;$('editText').value=pages[current].text;};$('cancelEdit').onclick=()=>{$('editor').hidden=true;setTabs('text');};$('saveEdit').onclick=()=>{pages[current].text=$('editText').value;resetPlayback();$('editor').hidden=true;setTabs('text');renderPage();notice('Teks bacaan diperbarui. Dokumen asli tidak berubah.');};
for(const id of ['upload','replace'])$(id).onclick=()=>$('file').click();$('file').onchange=e=>loadFile(e.target.files[0]);
$('drop').ondragover=e=>{e.preventDefault();$('drop').classList.add('drag');};$('drop').ondragleave=()=>$('drop').classList.remove('drag');$('drop').ondrop=e=>{e.preventDefault();$('drop').classList.remove('drag');loadFile(e.dataTransfer.files[0]);};
$('remove').onclick=async()=>{loading++;rendering++;cancel(true);previewTask?.cancel();await pdf?.destroy();pdf=null;pages=[];kind='';detected='und';$('empty').hidden=false;$('document').hidden=true;$('textView').replaceChildren();$('editText').value='';$('pdfCanvas').width=0;$('scope').disabled=true;$('pdfTab').disabled=true;$('rangeFields').hidden=true;$('file').value='';$('upload').disabled=false;status('');notice('');$('detected').textContent='Bahasa dikenali setelah dokumen dibuka.';refreshVoices();resetPlayback();};
$('demo').onclick=async()=>{loading++;rendering++;cancel(true);previewTask?.cancel();await pdf?.destroy();pdf=null;kind='demo';pages=[{text:'Ada banyak cara untuk menikmati sebuah cerita. Kadang, kita membacanya perlahan. Kadang, kita ingin memejamkan mata dan mendengarkan. Code Reader memberi ruang untuk keduanya.'},{text:'Bagaimana jika halaman yang panjang menjadi teman perjalanan? Pilih suara yang Anda sukai, atur kecepatannya, lalu dengarkan. Anda bisa berhenti sejenak, kembali ke kalimat sebelumnya, atau melanjutkan saat siap.'},{text:'Setiap hari adalah kesempatan untuk mempelajari sesuatu yang baru. Mulailah dari satu halaman, satu gagasan, dan satu langkah kecil. Selamat membaca!'}];showDocument('Satu halaman, satu cerita',0);$('upload').disabled=false;status('');notice('Ini teks contoh. Dokumen Anda sendiri dapat dibuka lewat tombol Buka dokumen.');};
$('theme').onclick=()=>{document.body.classList.toggle('dark');try{localStorage.setItem('code-reader-theme',document.body.classList.contains('dark')?'dark':'light');}catch{}};try{if(localStorage.getItem('code-reader-theme')==='dark')document.body.classList.add('dark');}catch{}
$('help').onclick=()=>$('guide').showModal();$('closeGuide').onclick=()=>$('guide').close();
window.addEventListener('pagehide',()=>speech?.cancel());if(speech){speech.addEventListener('voiceschanged',refreshVoices);refreshVoices();}else{notice('Browser ini belum mendukung pembacaan suara. Teks dokumen tetap bisa dibuka.');refreshVoices();}
